def two_sum_brute(a: list[int], target: int) -> tuple[int, int] | None:
    n = len(a)
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] + a[j] == target:
                return (i, j)
    return None

def two_sum(a: list[int], target: int) -> tuple[int, int] | None:
    seen: dict[int, int] = {}
    for i, x in enumerate(a):
        need = target - x
        if need in seen:
            return (seen[need], i)
        seen[x] = i
    return None

def two_sum_sorted(a: list[int], target: int) -> bool:
    a = sorted(a)
    lo, hi = 0, len(a) - 1
    while lo < hi:
        s = a[lo] + a[hi]
        if s == target:
            return True
        if s < target:
            lo += 1
        else:
            hi -= 1
    return False
